.ds-button {
  display: inline-flex;
  min-height: 56px;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 16px 24px;
  background: var(--primary);
  color: var(--paper);
  font-size: 16px;
  font-weight: 700;
  text-decoration: none;
  border: 0;
  border-radius: 8px;
  transition:
    transform 0.2s,
    opacity 0.2s;
}
.ds-button:hover {
  transform: translateY(-3px);
}
.ds-button:active {
  transform: translateY(1px);
}
.ds-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
.ds-button:focus-visible { outline: 3px solid currentColor; outline-offset: 5px; }
@media (prefers-reduced-motion: reduce) { .ds-button { transition: none; transform: none; } }

