.ds-inverse { padding: 24px; background: var(--primary, #223d32); } .ds-inverse .ds-button { background: var(--paper, #ffffff); color: var(--foreground, #223d32); }

.ds-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 24px;
}
.ds-field label {
  font-size: 16px;
  font-weight: 600;
}
.ds-field input,
.ds-field textarea,
.ds-field select {
  min-width: 0;
  width: 100%;
  background: var(--surface);
  padding: 14px;
  border: 1px solid var(--card-border);
  border-radius: 8px;
}
.ds-field input:focus-visible { outline: 3px solid currentColor; outline-offset: 5px; }
@media (prefers-reduced-motion: reduce) { .ds-field input { transition: none; transform: none; } }

.ds-text-link {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  text-decoration: underline;
  text-underline-offset: 6px;
  text-decoration-thickness: 1px;
  font-weight: 600;
}
.ds-text-link:hover {
  text-decoration-thickness: 2px;
}
.ds-text-link:focus-visible { outline: 3px solid currentColor; outline-offset: 5px; }
@media (prefers-reduced-motion: reduce) { .ds-text-link { transition: none; transform: none; } }

.ds-pricing-plan {
  display: grid;
  grid-row: span 5;
  grid-template-rows: subgrid;
  padding: 28px;
  background: var(--paper);
}
.ds-pricing-plan--plus {
  background: var(--foreground);
  color: var(--paper);
}
.ds-pricing-plan__price {
  font-family: var(--font-sans);
  font-weight: 600;
  font-size: clamp(44px, 4vw, 64px);
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}
.ds-pricing-plan a:focus-visible { outline: 3px solid currentColor; outline-offset: 5px; }
@media (prefers-reduced-motion: reduce) { .ds-pricing-plan a { transition: none; transform: none; } }
.ds-pricing-plan { grid-template-rows: auto; }
